from heapq import heappop, heappush


def fastest_delivery(n, roads, stations, capacity, swap_time, max_swaps, s, t):
    if s == t:
        return (0, 0)

    is_station = [False] * n
    for st in stations:
        is_station[st] = True

    adj = [[] for _ in range(n)]
    for u, v, m, e in roads:
        adj[u].append((v, m, e))

    C = capacity + 1
    K = max_swaps + 1
    CK = C * K
    INF = 10**18
    best_time = [INF] * (n * CK)
    max_c = [-1] * (n * K)

    best_time[(s * C + capacity) * K] = 0
    # Pack (t_cur, k, u, capacity - c) into one int for fast heap ordering:
    # bits 0..5: capacity - c (<= 40), bits 6..13: u (< 200),
    # bits 14..16: k (<= 6), bits 17..: t_cur
    pq = [s << 6]

    while pq:
        item = heappop(pq)
        t_cur = item >> 17
        k = (item >> 14) & 7
        u = (item >> 6) & 255
        c = capacity - (item & 63)

        uk_base = u * K
        if max_c[uk_base + k] >= c:
            continue

        if u == t:
            return (t_cur, k)

        for kk in range(k, K):
            if max_c[uk_base + kk] < c:
                max_c[uk_base + kk] = c
            else:
                break

        for v, m, e in adj[u]:
            if c < e:
                continue
            nc = c - e
            if nc > capacity:
                nc = capacity
            if max_c[v * K + k] >= nc:
                continue
            nt = t_cur + m
            idx = v * CK + nc * K + k
            if nt < best_time[idx]:
                best_time[idx] = nt
                heappush(pq, (nt << 17) | (k << 14) | (v << 6) | (capacity - nc))

        if is_station[u] and k < max_swaps and c < capacity:
            nk = k + 1
            if max_c[uk_base + nk] < capacity:
                nt = t_cur + swap_time
                idx = u * CK + capacity * K + nk
                if nt < best_time[idx]:
                    best_time[idx] = nt
                    heappush(pq, (nt << 17) | (nk << 14) | (u << 6))

    return None

from collections import deque


def best_context(messages, budget, max_gap, bonus):
    if budget < 0 or max_gap < 0:
        raise ValueError("budget and max_gap must be non-negative")

    n = len(messages)
    if n == 0:
        return 0

    NEG_INF = -10**18
    # dp[i][c] = max score over prefixes ending at i (with message i kept) and total length c
    dp = [[NEG_INF] * (budget + 1) for _ in range(n)]
    # deques[c] maintains a sliding-window maximum of dp[j][c] for j in [L, i - 2]
    deques = [deque() for _ in range(budget + 1)]
    last_pinned = -1

    for i, (length, value, pinned) in enumerate(messages):
        if i >= 2:
            j_add = i - 2
            dp_add = dp[j_add]
            for c in range(budget + 1):
                val = dp_add[c]
                if val != NEG_INF:
                    dq = deques[c]
                    while dq and dq[-1][1] <= val:
                        dq.pop()
                    dq.append((j_add, val))

        if length <= budget:
            L = last_pinned
            gap_limit = i - 1 - max_gap
            if gap_limit > L:
                L = gap_limit

            dp_i = dp[i]
            can_start = (last_pinned == -1 and i <= max_gap)
            dp_prev = dp[i - 1] if i >= 1 else None

            for prev_c in range(budget - length + 1):
                best_prev = 0 if (can_start and prev_c == 0) else NEG_INF

                if dp_prev is not None:
                    v = dp_prev[prev_c]
                    if v != NEG_INF:
                        cand = v + bonus
                        if cand > best_prev:
                            best_prev = cand

                dq = deques[prev_c]
                while dq and dq[0][0] < L:
                    dq.popleft()
                if dq:
                    cand = dq[0][1]
                    if cand > best_prev:
                        best_prev = cand

                if best_prev != NEG_INF:
                    dp_i[prev_c + length] = best_prev + value

        if pinned:
            last_pinned = i

    ans = 0 if (last_pinned == -1 and n <= max_gap) else NEG_INF
    start_i = max(0, last_pinned, n - 1 - max_gap)
    for i in range(start_i, n):
        m = max(dp[i])
        if m > ans:
            ans = m

    return None if ans == NEG_INF else ans

def min_pruning_cost(parent, demand, cap, cut_cost, critical, root_cap, penalty):
    n = len(parent)
    children = [[] for _ in range(n)]
    for v in range(1, n):
        children[parent[v]].append(v)

    # Iterative DFS to get a topological ordering (parent before children)
    order = []
    stack = [0]
    while stack:
        u = stack.pop()
        order.append(u)
        for c in children[u]:
            stack.append(c)

    # Compute subtree demand and whether each subtree contains a critical node
    sub_dem = list(demand)
    has_crit = list(critical)
    for v in reversed(order):
        for c in children[v]:
            sub_dem[v] += sub_dem[c]
            if has_crit[c]:
                has_crit[v] = True

    INF = 10**18
    # dp[v] will store sorted (load, min_cost) pairs for node v assuming v is retained
    dp = [None] * n

    for v in reversed(order):
        lim = root_cap if v == 0 else cap[v]
        if demand[v] > lim:
            if has_crit[v] or v == 0:
                return None
            dp[v] = []
            continue

        dp_v = [INF] * (demand[v] + 1)
        dp_v[demand[v]] = 0
        possible = True

        for c in children[v]:
            valid_c = dp[c]
            dp[c] = None  # free memory no longer needed
            can_cut = not has_crit[c]

            if not valid_c:
                if not can_cut:
                    possible = False
                    break
                cut_val = cut_cost[c] + penalty * sub_dem[c]
                for l in range(len(dp_v)):
                    if dp_v[l] < INF:
                        dp_v[l] += cut_val
                continue

            valid_v = [(l, cost) for l, cost in enumerate(dp_v) if cost < INF]
            max_new_l = min(lim, valid_v[-1][0] + valid_c[-1][0])
            new_dp = [INF] * (max_new_l + 1)

            if can_cut:
                cut_val = cut_cost[c] + penalty * sub_dem[c]
                for l_v, cost_v in valid_v:
                    new_dp[l_v] = cost_v + cut_val

            for l_v, cost_v in valid_v:
                max_lc = lim - l_v
                for l_c, cost_c in valid_c:
                    if l_c > max_lc:
                        break
                    nl = l_v + l_c
                    nc = cost_v + cost_c
                    if nc < new_dp[nl]:
                        new_dp[nl] = nc

            if min(new_dp) == INF:
                possible = False
                break
            dp_v = new_dp

        if not possible:
            if has_crit[v] or v == 0:
                return None
            dp[v] = []
        else:
            dp[v] = [(l, cost) for l, cost in enumerate(dp_v) if cost < INF]
            if not dp[v] and (has_crit[v] or v == 0):
                return None

    return min(cost for _, cost in dp[0])

from operator import itemgetter


def earliest_arrival(connections, transfer, source, target, start_time, max_boardings):
    if source == target:
        return start_time
    if max_boardings == 0 or not connections:
        return None

    n = len(transfer)
    limit = max_boardings if max_boardings < n else n - 1

    # Group connections by trip_id
    trips_raw = {}
    for conn in connections:
        tid = conn[0]
        lst = trips_raw.get(tid)
        if lst is None:
            trips_raw[tid] = [conn]
        else:
            lst.append(conn)

    num_trips = len(trips_raw)
    trip_stops = [None] * num_trips
    trip_ptr = [0] * num_trips
    out = [[] for _ in range(n)]

    get_dep = itemgetter(3)
    for t_idx, t_conns in enumerate(trips_raw.values()):
        if len(t_conns) > 1:
            t_conns.sort(key=get_dep)
        stops = []
        for pos, (_, u, v, dep, arr) in enumerate(t_conns):
            out[u].append((dep, t_idx, pos))
            stops.append((v, arr))
        trip_stops[t_idx] = stops
        trip_ptr[t_idx] = len(stops)

    get_first = itemgetter(0)
    depart_ptr = [0] * n
    for u in range(n):
        ou = out[u]
        if len(ou) > 1:
            ou.sort(key=get_first)
        depart_ptr[u] = len(ou)

    if depart_ptr[source] == 0:
        return None

    INF = 10**25
    best_ready = [INF] * n
    best_ready[source] = start_time
    best_target = INF

    in_next = [False] * n
    cur_queue = [source]

    for _ in range(limit):
        if not cur_queue:
            break
        # Snapshot ready times from the previous round so in-round updates
        # do not leak into the current round's boardings.
        snap = [(u, best_ready[u]) for u in cur_queue]
        next_queue = []

        for u, r_u in snap:
            if r_u >= best_target:
                continue
            ptr = depart_ptr[u]
            ou = out[u]
            while ptr > 0:
                dep, t_idx, pos = ou[ptr - 1]
                if dep < r_u:
                    break
                ptr -= 1
                t_end = trip_ptr[t_idx]
                if pos < t_end:
                    trip_ptr[t_idx] = pos
                    stops = trip_stops[t_idx]
                    for i in range(pos, t_end):
                        v, arr = stops[i]
                        if arr >= best_target:
                            break
                        if v == target:
                            best_target = arr
                        elif depart_ptr[v] > 0:
                            r_v = arr + transfer[v]
                            if r_v < best_ready[v] and r_v < best_target:
                                best_ready[v] = r_v
                                if not in_next[v]:
                                    in_next[v] = True
                                    next_queue.append(v)
            depart_ptr[u] = ptr

        for v in next_queue:
            in_next[v] = False
        cur_queue = next_queue

    return None if best_target == INF else best_target

from collections import deque


def run_kiosk(levels, threshold, patience, arrivals):
    n = len(arrivals)
    for i in range(1, n):
        if arrivals[i][0] < arrivals[i - 1][0]:
            raise ValueError("arrivals must be in non-decreasing order of time")

    num_slots = len(levels)
    t0 = [0] * num_slots
    c0 = list(levels)
    ready_time = [threshold - c if c < threshold else 0 for c in c0]

    queue = deque()
    out = []

    def serve_queue(t):
        while queue:
            best_slot = -1
            best_charge = -1
            for k in range(num_slots):
                if ready_time[k] <= t:
                    ch = c0[k] + (t - t0[k])
                    if ch > 100:
                        ch = 100
                    if ch > best_charge:
                        best_charge = ch
                        best_slot = k
            if best_slot == -1:
                break
            _, drone, charge = queue.popleft()
            out.append((drone, "SWAP", t, best_slot))
            t0[best_slot] = t
            c0[best_slot] = charge
            ready_time[best_slot] = t + (threshold - charge if charge < threshold else 0)

    def advance_before(t_limit):
        while queue:
            next_ready = min(ready_time)
            next_leave = queue[0][0] + patience
            t_event = next_ready if next_ready < next_leave else next_leave
            if t_limit is not None and t_event >= t_limit:
                break
            serve_queue(t_event)
            while queue and queue[0][0] + patience <= t_event:
                _, drone, _ = queue.popleft()
                out.append((drone, "LEFT", t_event))

    idx = 0
    while idx < n:
        t_arr = arrivals[idx][0]
        advance_before(t_arr)

        # 1. Serve the queue at t_arr
        serve_queue(t_arr)

        # 2. Handle arrivals at t_arr in list order
        while idx < n and arrivals[idx][0] == t_arr:
            _, drone, charge = arrivals[idx]
            idx += 1
            if queue:
                queue.append((t_arr, drone, charge))
            else:
                best_slot = -1
                best_charge = -1
                for k in range(num_slots):
                    if ready_time[k] <= t_arr:
                        ch = c0[k] + (t_arr - t0[k])
                        if ch > 100:
                            ch = 100
                        if ch > best_charge:
                            best_charge = ch
                            best_slot = k
                if best_slot != -1:
                    out.append((drone, "SWAP", t_arr, best_slot))
                    t0[best_slot] = t_arr
                    c0[best_slot] = charge
                    ready_time[best_slot] = t_arr + (threshold - charge if charge < threshold else 0)
                else:
                    queue.append((t_arr, drone, charge))

        # 3. Give up at t_arr
        while queue and queue[0][0] + patience <= t_arr:
            _, drone, _ = queue.popleft()
            out.append((drone, "LEFT", t_arr))

    advance_before(None)
    return out

from collections import defaultdict


def run_lock_manager(ops):
    ACTIVE = 0
    WAITING = 1
    FINISHED = 2

    STEP = 1 << 60
    min_tag = 0
    max_tag = STEP

    state = {}
    ord_map = {}
    used_tags = set()
    tx_locks = {}
    tx_locked_queued = {}

    q_res = {}
    q_mode = {}
    q_is_up = {}
    q_prev = {}
    q_next = {}

    s_holders = defaultdict(set)
    x_holder = {}
    q_head = {}
    q_tail = {}
    q_up_tail = {}

    logs = []

    def add_holder(tx, res, mode):
        tx_locks[tx][res] = mode
        if mode == "S":
            s_holders[res].add(tx)
        else:
            x_holder[res] = tx
        if q_head.get(res) is not None:
            tx_locked_queued[tx].add(res)

    def upgrade_holder(tx, res):
        tx_locks[tx][res] = "X"
        s_holders[res].remove(tx)
        x_holder[res] = tx

    def remove_holder(tx, res):
        mode = tx_locks[tx].pop(res)
        if mode == "S":
            s_holders[res].remove(tx)
        else:
            x_holder[res] = None
        tx_locked_queued[tx].discard(res)

    def enqueue(tx, res, mode, is_up):
        old_h = q_head.get(res)
        state[tx] = WAITING
        q_res[tx] = res
        q_mode[tx] = mode
        q_is_up[tx] = is_up
        if old_h is None:
            q_head[res] = q_tail[res] = tx
            q_prev[tx] = q_next[tx] = None
            q_up_tail[res] = tx if is_up else None
            xh = x_holder.get(res)
            if xh is not None:
                tx_locked_queued[xh].add(res)
            else:
                for h in s_holders[res]:
                    tx_locked_queued[h].add(res)
        else:
            if is_up:
                ut = q_up_tail.get(res)
                if ut is None:
                    q_prev[tx] = None
                    q_next[tx] = old_h
                    q_prev[old_h] = tx
                    q_head[res] = tx
                else:
                    nxt = q_next[ut]
                    q_prev[tx] = ut
                    q_next[tx] = nxt
                    q_next[ut] = tx
                    if nxt is None:
                        q_tail[res] = tx
                    else:
                        q_prev[nxt] = tx
                q_up_tail[res] = tx
            else:
                old_t = q_tail[res]
                q_prev[tx] = old_t
                q_next[tx] = None
                q_next[old_t] = tx
                q_tail[res] = tx

    def dequeue(tx, res):
        prv = q_prev[tx]
        nxt = q_next[tx]
        if prv is None:
            q_head[res] = nxt
        else:
            q_next[prv] = nxt
        if nxt is None:
            q_tail[res] = prv
        else:
            q_prev[nxt] = prv
        if q_up_tail.get(res) == tx:
            q_up_tail[res] = prv
        q_prev[tx] = q_next[tx] = None
        q_res[tx] = None
        if q_head[res] is None:
            xh = x_holder.get(res)
            if xh is not None:
                tx_locked_queued[xh].discard(res)
            else:
                for h in s_holders[res]:
                    tx_locked_queued[h].discard(res)

    def release(tx, op_idx):
        affected = set(tx_locks[tx].keys())
        if state[tx] == WAITING:
            r_wait = q_res[tx]
            affected.add(r_wait)
            dequeue(tx, r_wait)
        for res in list(tx_locks[tx].keys()):
            remove_holder(tx, res)
        state[tx] = FINISHED
        used_tags.discard(ord_map.pop(tx))

        for res in sorted(affected):
            while True:
                u = q_head.get(res)
                if u is None:
                    break
                m = q_mode[u]
                is_up = q_is_up[u]
                if is_up:
                    grantable = len(s_holders[res]) == 1
                elif m == "S":
                    grantable = x_holder.get(res) is None
                else:
                    grantable = x_holder.get(res) is None and not s_holders[res]
                if not grantable:
                    break
                dequeue(u, res)
                state[u] = ACTIVE
                if is_up:
                    upgrade_holder(u, res)
                else:
                    add_holder(u, res, m)
                logs.append(("GRANT", op_idx, u, res, m))

    def get_out_neighbors(u):
        res = q_res[u]
        if res is None:
            return ()
        if u != q_head[res]:
            return (q_prev[u],)
        xh = x_holder.get(res)
        if xh is not None:
            return (xh,)
        return [h for h in s_holders[res] if h != u]

    def get_in_neighbors(v):
        res_list = []
        if q_res[v] is not None:
            nxt = q_next[v]
            if nxt is not None:
                res_list.append(nxt)
        for res in tx_locked_queued[v]:
            h = q_head[res]
            if h is not None and h != v:
                res_list.append(h)
        return res_list

    def global_respace():
        nonlocal min_tag, max_tag
        nodes = sorted(ord_map, key=ord_map.__getitem__)
        used_tags.clear()
        tag = STEP
        for n in nodes:
            ord_map[n] = tag
            used_tags.add(tag)
            tag += STEP
        min_tag = 0
        max_tag = tag

    def place_between(node, lo_node, hi_node):
        used_tags.discard(ord_map[node])
        lo = ord_map[lo_node]
        hi = ord_map[hi_node]
        while True:
            if hi - lo < 2:
                global_respace()
                used_tags.discard(ord_map[node])
                lo = ord_map[lo_node]
                hi = ord_map[hi_node]
            mid = (lo + hi) >> 1
            if mid not in used_tags:
                ord_map[node] = mid
                used_tags.add(mid)
                return
            if mid - lo >= 2:
                hi = mid
            elif hi - mid >= 2:
                lo = mid
            else:
                global_respace()
                used_tags.discard(ord_map[node])
                lo = ord_map[lo_node]
                hi = ord_map[hi_node]

    def resolve_deadlocks(t, op_idx):
        nonlocal min_tag
        while state[t] == WAITING:
            out_t = get_out_neighbors(t)
            in_t = get_in_neighbors(t)
            if not in_t:
                min_out = min(ord_map[v] for v in out_t)
                if ord_map[t] >= min_out:
                    used_tags.discard(ord_map[t])
                    ord_map[t] = min_tag
                    used_tags.add(min_tag)
                    min_tag -= STEP
                break

            lo_node = max(in_t, key=ord_map.__getitem__)
            hi_node = min(out_t, key=ord_map.__getitem__)
            max_in = ord_map[lo_node]
            min_out = ord_map[hi_node]

            if max_in < min_out:
                if not (max_in < ord_map[t] < min_out):
                    place_between(t, lo_node, hi_node)
                break

            fwd = set()
            stack = []
            for v in out_t:
                if ord_map[v] <= max_in and v not in fwd:
                    fwd.add(v)
                    stack.append(v)
            while stack:
                x = stack.pop()
                for y in get_out_neighbors(x):
                    if y != t and ord_map[y] <= max_in and y not in fwd:
                        fwd.add(y)
                        stack.append(y)

            bwd = set()
            stack = []
            for u in in_t:
                if ord_map[u] >= min_out and u not in bwd:
                    bwd.add(u)
                    stack.append(u)
            while stack:
                x = stack.pop()
                for y in get_in_neighbors(x):
                    if y != t and ord_map[y] >= min_out and y not in bwd:
                        bwd.add(y)
                        stack.append(y)

            scc_rest = fwd & bwd
            if not scc_rest:
                b_sorted = sorted(bwd, key=ord_map.__getitem__)
                f_sorted = sorted(fwd, key=ord_map.__getitem__)
                combined = b_sorted + f_sorted
                tags = sorted(ord_map[x] for x in combined)
                for node, tag in zip(combined, tags):
                    ord_map[node] = tag
                place_between(t, b_sorted[-1], f_sorted[0])
                break

            victim = max(t, max(scc_rest))
            logs.append(("ABORT", op_idx, victim))
            release(victim, op_idx)
            if victim == t:
                break

    for i, op in enumerate(ops):
        kind = op[0]
        tx = op[1]
        st = state.get(tx)
        if st is None:
            state[tx] = ACTIVE
            ord_map[tx] = max_tag
            used_tags.add(max_tag)
            max_tag += STEP
            tx_locks[tx] = {}
            tx_locked_queued[tx] = set()
            q_res[tx] = None
            q_prev[tx] = None
            q_next[tx] = None
            st = ACTIVE

        if st != ACTIVE:
            logs.append(("IGNORED", i, tx))
            continue

        if kind == "COMMIT":
            logs.append(("COMMIT", i, tx))
            release(tx, i)
            continue

        res = op[2]
        held = tx_locks[tx].get(res)
        if held == "X" or (held == "S" and kind == "S"):
            logs.append(("HELD", i, tx, res))
            continue

        if held == "S" and kind == "X":
            if len(s_holders[res]) == 1:
                upgrade_holder(tx, res)
                logs.append(("GRANT", i, tx, res, "X"))
                continue
            enqueue(tx, res, "X", True)
            logs.append(("WAIT", i, tx, res, "X"))
            resolve_deadlocks(tx, i)
            continue

        if q_head.get(res) is None:
            if kind == "S":
                compat = x_holder.get(res) is None
            else:
                compat = x_holder.get(res) is None and not s_holders[res]
            if compat:
                add_holder(tx, res, kind)
                logs.append(("GRANT", i, tx, res, kind))
                continue

        enqueue(tx, res, kind, False)
        logs.append(("WAIT", i, tx, res, kind))
        resolve_deadlocks(tx, i)

    return logs

def simulate_vending(prices, stock, bank, events, timeout):
    prev_t = None
    for ev in events:
        t = ev[0]
        if prev_t is not None and t < prev_t:
            raise ValueError("Event timestamps must be non-decreasing")
        prev_t = t

    cur_stock = dict(stock)
    b5 = bank.get(5, 0)
    b10 = bank.get(10, 0)
    b25 = bank.get(25, 0)
    b100 = bank.get(100, 0)

    accepted = {5, 10, 25, 100}
    escrow = []
    escrow_total = 0
    last = 0
    log = []

    for t, kind, arg in events:
        if escrow and t >= last + timeout:
            log.append(("TIMEOUT", last + timeout, tuple(sorted(escrow, reverse=True))))
            escrow.clear()
            escrow_total = 0

        if kind == "coin":
            if arg not in accepted or len(escrow) == 10:
                log.append(("REJECT", t, arg))
            else:
                escrow.append(arg)
                escrow_total += arg
                last = t
        elif kind == "select":
            last = t
            if arg not in prices:
                log.append(("UNKNOWN", t, arg))
            elif cur_stock[arg] == 0:
                log.append(("SOLD_OUT", t, arg))
            elif escrow_total < prices[arg]:
                log.append(("NEED", t, prices[arg] - escrow_total))
            else:
                t5, t10, t25, t100 = b5, b10, b25, b100
                for c in escrow:
                    if c == 5:
                        t5 += 1
                    elif c == 10:
                        t10 += 1
                    elif c == 25:
                        t25 += 1
                    else:
                        t100 += 1

                rem = escrow_total - prices[arg]
                k100 = min(t100, rem // 100)
                rem -= k100 * 100
                t100 -= k100

                k25 = min(t25, rem // 25)
                rem -= k25 * 25
                t25 -= k25

                k10 = min(t10, rem // 10)
                rem -= k10 * 10
                t10 -= k10

                k5 = min(t5, rem // 5)
                rem -= k5 * 5
                t5 -= k5

                if rem == 0:
                    b5, b10, b25, b100 = t5, t10, t25, t100
                    cur_stock[arg] -= 1
                    escrow.clear()
                    escrow_total = 0
                    change_coins = (100,) * k100 + (25,) * k25 + (10,) * k10 + (5,) * k5
                    log.append(("VEND", t, arg, change_coins))
                else:
                    log.append(("EXACT_ONLY", t, arg))
        elif kind == "cancel":
            last = t
            if escrow:
                log.append(("RETURN", t, tuple(sorted(escrow, reverse=True))))
                escrow.clear()
                escrow_total = 0

    if escrow:
        log.append(("TIMEOUT", last + timeout, tuple(sorted(escrow, reverse=True))))
        escrow.clear()

    return log, (b5, b10, b25, b100)

import re

_NAME_RE = re.compile(r"[a-z0-9_]+", re.ASCII)
_ACTION_WORD_RE = re.compile(r"[a-z]+", re.ASCII)
_SEGMENT_RE = re.compile(r"[a-z0-9._-]+", re.ASCII)


def _match_glob(pat: tuple[str, ...], segs: tuple[str, ...]) -> bool:
    """Match a collapsed resource pattern against path segments in O(|pat| * |segs|) worst-case time."""
    m = len(pat)
    n = len(segs)
    pi = 0
    si = 0
    star_pi = -1
    star_si = 0

    while si < n:
        if pi < m and (pat[pi] == segs[si] or pat[pi] == "*"):
            pi += 1
            si += 1
        elif pi < m and pat[pi] == "**":
            star_pi = pi
            star_si = si
            pi += 1
            if pi == m:
                return True
        elif star_pi != -1:
            pi = star_pi + 1
            star_si += 1
            si = star_si
        else:
            return False

    while pi < m and pat[pi] == "**":
        pi += 1
    return pi == m


def evaluate_access(rules, requests) -> list[str]:
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    if not isinstance(requests, list):
        raise TypeError("requests must be a list")

    wildcard_rules = []
    rules_by_user: dict[str, list] = {}
    rules_by_group: dict[str, list] = {}

    # Validate and compile all rules in index order
    for i, rule in enumerate(rules):
        if not isinstance(rule, str):
            raise TypeError(f"rule {i}: not a str")

        fields = rule.split()
        if len(fields) != 4:
            raise ValueError(f"rule {i}: expected 4 fields, got {len(fields)}")
        effect, principal, action, resource = fields

        if effect != "ALLOW" and effect != "DENY":
            raise ValueError(f"rule {i}: bad effect {effect!r}")

        if principal == "*":
            p_spec = 0
            p_kind = 0
            p_name = ""
        elif principal.startswith("user:") and _NAME_RE.fullmatch(principal[5:]):
            p_spec = 2
            p_kind = 1
            p_name = principal[5:]
        elif principal.startswith("group:") and _NAME_RE.fullmatch(principal[6:]):
            p_spec = 1
            p_kind = 2
            p_name = principal[6:]
        else:
            raise ValueError(f"rule {i}: bad principal {principal!r}")

        if action == "*":
            a_spec = 0
            action_set = None
        else:
            parts = action.split(",")
            if not all(_ACTION_WORD_RE.fullmatch(part) for part in parts):
                raise ValueError(f"rule {i}: bad action {action!r}")
            a_spec = 1
            action_set = frozenset(parts)

        if resource == "/":
            raw_segs = []
        elif resource.startswith("/"):
            raw_segs = resource[1:].split("/")
            for seg in raw_segs:
                if seg != "*" and seg != "**" and not _SEGMENT_RE.fullmatch(seg):
                    raise ValueError(f"rule {i}: bad resource {resource!r}")
        else:
            raise ValueError(f"rule {i}: bad resource {resource!r}")

        l_spec = 0
        collapsed = []
        has_star = False
        has_dstar = False
        for seg in raw_segs:
            if seg == "**":
                has_dstar = True
                if not collapsed or collapsed[-1] != "**":
                    collapsed.append("**")
            elif seg == "*":
                has_star = True
                collapsed.append("*")
            else:
                l_spec += 1
                collapsed.append(seg)

        pat = tuple(collapsed)
        if has_dstar:
            if pat == ("**",):
                res_mode = 0
                min_len = 0
            else:
                res_mode = 3
                min_len = sum(1 for seg in pat if seg != "**")
        elif has_star:
            res_mode = 2
            min_len = len(pat)
        else:
            res_mode = 1
            min_len = len(pat)

        # Higher key wins: (L, P, A), then DENY over ALLOW, then smaller rule index
        key = (l_spec, p_spec, a_spec, 1 if effect == "DENY" else 0, -i)
        decision = f"{effect} by rule {i}"
        compiled = (key, decision, action_set, res_mode, pat, min_len)

        if p_kind == 0:
            wildcard_rules.append(compiled)
        elif p_kind == 1:
            rules_by_user.setdefault(p_name, []).append(compiled)
        else:
            rules_by_group.setdefault(p_name, []).append(compiled)

    # Validate and parse all requests in index order
    parsed_requests = []
    for j, req in enumerate(requests):
        if not isinstance(req, tuple) or len(req) != 4:
            raise TypeError(f"request {j}: expected 4-tuple")
        user, groups, action, path = req

        if not isinstance(user, str) or not _NAME_RE.fullmatch(user):
            raise ValueError(f"request {j}: bad user {user!r}")

        if not isinstance(groups, list) or not all(
            isinstance(g, str) and _NAME_RE.fullmatch(g) for g in groups
        ):
            raise ValueError(f"request {j}: bad groups")

        if not isinstance(action, str) or not _ACTION_WORD_RE.fullmatch(action):
            raise ValueError(f"request {j}: bad action {action!r}")

        if not isinstance(path, str):
            raise ValueError(f"request {j}: bad path {path!r}")
        if path == "/":
            segs = ()
        elif path.startswith("/"):
            raw_path_segs = path[1:].split("/")
            for seg in raw_path_segs:
                if not _SEGMENT_RE.fullmatch(seg):
                    raise ValueError(f"request {j}: bad path {path!r}")
            segs = tuple(raw_path_segs)
        else:
            raise ValueError(f"request {j}: bad path {path!r}")

        parsed_requests.append((user, groups, action, segs))

    if not parsed_requests:
        return []

    # Sort each bucket by winning priority descending for early pruning
    wildcard_rules.sort(key=lambda r: r[0], reverse=True)
    for lst in rules_by_user.values():
        lst.sort(key=lambda r: r[0], reverse=True)
    for lst in rules_by_group.values():
        lst.sort(key=lambda r: r[0], reverse=True)

    results: list[str] = []
    for user, groups, action, segs in parsed_requests:
        best_key = None
        best_decision = "DENY by default"
        n_segs = len(segs)

        cand_lists = []
        u_rules = rules_by_user.get(user)
        if u_rules is not None:
            cand_lists.append(u_rules)

        if len(groups) == 1:
            g_rules = rules_by_group.get(groups[0])
            if g_rules is not None:
                cand_lists.append(g_rules)
        elif groups:
            seen_groups = set()
            for g in groups:
                if g not in seen_groups:
                    seen_groups.add(g)
                    g_rules = rules_by_group.get(g)
                    if g_rules is not None:
                        cand_lists.append(g_rules)

        if wildcard_rules:
            cand_lists.append(wildcard_rules)

        for cand_list in cand_lists:
            for rule in cand_list:
                key = rule[0]
                if best_key is not None and key <= best_key:
                    break

                action_set = rule[2]
                if action_set is not None and action not in action_set:
                    continue

                res_mode = rule[3]
                if res_mode == 0:
                    matched = True
                elif res_mode == 1:
                    matched = segs == rule[4]
                elif res_mode == 2:
                    matched = n_segs == rule[5] and all(
                        p == s or p == "*" for p, s in zip(rule[4], segs)
                    )
                else:
                    matched = n_segs >= rule[5] and _match_glob(rule[4], segs)

                if matched:
                    best_key = key
                    best_decision = rule[1]
                    break

        results.append(best_decision)

    return results

import json
import re

_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*", re.ASCII)


def _type_name(v) -> str:
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "bool"
    if isinstance(v, int):
        return "int"
    if isinstance(v, float):
        return "float"
    if isinstance(v, str):
        return "str"
    if isinstance(v, list):
        return "list"
    if isinstance(v, dict):
        return "dict"
    return type(v).__name__


def _clone(v):
    if isinstance(v, dict):
        return {k: _clone(val) for k, val in v.items()}
    if isinstance(v, list):
        return [_clone(item) for item in v]
    return v


def _child_path(parent: str, name: str) -> str:
    if _IDENT_RE.fullmatch(name):
        return f"{parent}.{name}"
    return f"{parent}[{json.dumps(name, ensure_ascii=False)}]"


def merge_layers(layers) -> tuple[dict, list[str]]:
    if not isinstance(layers, list):
        raise TypeError("layers must be a list")

    result: dict = {}
    warnings: list[str] = []

    def _merge(overlay: dict, target: dict, path: str, layer_idx: int) -> None:
        for k, v in overlay.items():
            if not isinstance(k, str):
                raise TypeError(f"layer {layer_idx}: non-string key at {path}")

            if k.startswith("-"):
                mode = "DELETE"
                name = k[1:]
            elif k.endswith("+"):
                mode = "APPEND"
                name = k[:-1]
            else:
                mode = "SET"
                name = k

            if name == "":
                raise ValueError(f"layer {layer_idx}: empty key name at {path}")

            q = _child_path(path, name)

            if mode == "DELETE":
                if v is not None:
                    raise ValueError(
                        f"layer {layer_idx}: delete directive needs null at {q}"
                    )
                if name in target:
                    del target[name]
                else:
                    warnings.append(
                        f"layer {layer_idx}: delete of missing key at {q}"
                    )
            elif mode == "APPEND":
                if not isinstance(v, list):
                    raise ValueError(
                        f"layer {layer_idx}: append directive needs a list at {q}"
                    )
                if name not in target:
                    target[name] = _clone(v)
                elif isinstance(target[name], list):
                    target[name].extend(_clone(v))
                else:
                    raise ValueError(
                        f"layer {layer_idx}: cannot append to {_type_name(target[name])} at {q}"
                    )
            else:
                if name in target:
                    old_type = _type_name(target[name])
                    new_type = _type_name(v)
                    if old_type != new_type:
                        warnings.append(
                            f"layer {layer_idx}: type change at {q}: {old_type} -> {new_type}"
                        )

                if isinstance(v, dict):
                    if name not in target or not isinstance(target[name], dict):
                        target[name] = {}
                    _merge(v, target[name], q, layer_idx)
                else:
                    target[name] = _clone(v)

    for layer_idx, layer in enumerate(layers):
        if not isinstance(layer, dict):
            raise TypeError(f"layer {layer_idx} is not a dict")
        _merge(layer, result, "$", layer_idx)

    return result, warnings

import re

_PART_RE = r"(?:0|[1-9][0-9]*)"
_VERSION_RE = re.compile(rf"({_PART_RE})\.({_PART_RE})\.({_PART_RE})(?:~rc([1-9][0-9]*))?")
_XY_RE = re.compile(rf"({_PART_RE})\.({_PART_RE})")
_X_RE = re.compile(rf"({_PART_RE})")


def _parse_version(s: str):
    m = _VERSION_RE.fullmatch(s)
    if m is None:
        return None
    x, y, z, rc = m.groups()
    if rc is None:
        return (int(x), int(y), int(z), 1, 0)
    return (int(x), int(y), int(z), 0, int(rc))


def _parse_clause(clause: str):
    if clause == "*":
        return lambda v: True
    if clause.startswith("!="):
        target = _parse_version(clause[2:])
        return None if target is None else (lambda v, t=target: v != t)
    if clause.startswith(">="):
        target = _parse_version(clause[2:])
        return None if target is None else (lambda v, t=target: v >= t)
    if clause.startswith("<="):
        target = _parse_version(clause[2:])
        return None if target is None else (lambda v, t=target: v <= t)
    if clause.startswith(">"):
        target = _parse_version(clause[1:])
        return None if target is None else (lambda v, t=target: v > t)
    if clause.startswith("<"):
        target = _parse_version(clause[1:])
        return None if target is None else (lambda v, t=target: v < t)
    if clause.startswith("="):
        target = _parse_version(clause[1:])
        return None if target is None else (lambda v, t=target: v == t)
    if clause.startswith("@"):
        m = _XY_RE.fullmatch(clause[1:])
        if m is None:
            return None
        x, y = int(m.group(1)), int(m.group(2))
        return lambda v, x=x, y=y: v[0] == x and v[1] >= y
    if clause.endswith(".*"):
        prefix = clause[:-2]
        m = _XY_RE.fullmatch(prefix)
        if m is not None:
            x, y = int(m.group(1)), int(m.group(2))
            return lambda v, x=x, y=y: v[0] == x and v[1] == y
        m = _X_RE.fullmatch(prefix)
        if m is not None:
            x = int(m.group(1))
            return lambda v, x=x: v[0] == x
        return None
    target = _parse_version(clause)
    return None if target is None else (lambda v, t=target: v == t)


def pick_version(available, constraint) -> str | None:
    if not isinstance(available, list):
        raise TypeError("available must be a list")

    parsed_available = []
    for i, element in enumerate(available):
        if not isinstance(element, str):
            raise ValueError(f"invalid version at index {i}: {element!r}")
        ver = _parse_version(element)
        if ver is None:
            raise ValueError(f"invalid version at index {i}: {element!r}")
        parsed_available.append((element, ver))

    if not isinstance(constraint, str):
        raise TypeError("constraint must be a str")
    if constraint.strip(" ") == "":
        raise ValueError("empty constraint")

    parsed_alts = []
    for a, raw_alt in enumerate(constraint.split("|"), start=1):
        alt = raw_alt.strip(" ")
        allow_rc = False
        if alt.startswith("?"):
            allow_rc = True
            alt = alt[1:].strip(" ")
        if alt == "":
            raise ValueError(f"alternative {a} is empty")

        predicates = []
        for c, raw_clause in enumerate(alt.split(","), start=1):
            clause = raw_clause.strip(" ")
            pred = _parse_clause(clause)
            if pred is None:
                raise ValueError(f"alternative {a}, clause {c}: invalid clause {clause!r}")
            predicates.append(pred)

        parsed_alts.append((allow_rc, predicates))

    best_ver = None
    best_str = None
    for s, ver in parsed_available:
        is_rc = ver[3] == 0
        for allow_rc, predicates in parsed_alts:
            if is_rc and not allow_rc:
                continue
            if all(pred(ver) for pred in predicates):
                if best_ver is None or ver > best_ver:
                    best_ver = ver
                    best_str = s
                break

    return best_str

import re

_KEY_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_-]*")
_INT_RE = re.compile(r"-?(?:0|[1-9][0-9]*)")


def _parse_scalar(text: str, lineno: int):
    if text[0] == '"':
        if "\\" not in text:
            q = text.find('"', 1)
            if q != len(text) - 1:
                return None, ("error", lineno, "bad string")
            return text[1:-1], None

        out = []
        i = 1
        n = len(text)
        while i < n:
            ch = text[i]
            if ch == '"':
                if i != n - 1:
                    return None, ("error", lineno, "bad string")
                return "".join(out), None
            if ch == "\\":
                i += 1
                if i >= n:
                    return None, ("error", lineno, "bad escape")
                esc = text[i]
                if esc == "\\":
                    out.append("\\")
                elif esc == '"':
                    out.append('"')
                elif esc == "n":
                    out.append("\n")
                elif esc == "t":
                    out.append("\t")
                else:
                    return None, ("error", lineno, "bad escape")
            else:
                out.append(ch)
            i += 1
        return None, ("error", lineno, "bad string")

    if text == "true":
        return True, None
    if text == "false":
        return False, None
    if text == "null":
        return None, None
    if _INT_RE.fullmatch(text) is not None:
        return int(text), None
    return text, None


def parse_outline(text: str) -> tuple:
    stack = []
    root = None
    opener = None

    for lineno, line in enumerate(text.split("\n"), 1):
        rest = line.lstrip(" \t")
        if not rest or rest[0] == "#":
            continue

        indent = len(line) - len(rest)
        if indent and line.find("\t", 0, indent) != -1:
            return ("error", lineno, "tab in indentation")

        if rest[0] == "-" and (len(rest) == 1 or rest[1] == " "):
            kind = "item"
            key = None
            text_val = rest[2:].strip(" ")
            is_opener = text_val == ""
        else:
            colon = rest.find(":")
            if colon <= 0:
                return ("error", lineno, "invalid entry")
            key = rest[:colon]
            if _KEY_RE.fullmatch(key) is None:
                return ("error", lineno, "invalid entry")
            after_idx = colon + 1
            if after_idx == len(rest):
                is_opener = True
                text_val = ""
            elif rest[after_idx] != " ":
                return ("error", lineno, "invalid entry")
            else:
                text_val = rest[after_idx:].strip(" ")
                is_opener = text_val == ""
            kind = "key"

        if is_opener:
            value = None
        else:
            value, err = _parse_scalar(text_val, lineno)
            if err is not None:
                return err

        if not stack:
            if indent != 0:
                return ("error", lineno, "unexpected indent")
            if kind == "key":
                container = {key: value}
                stack.append((0, "key", container))
                if is_opener:
                    opener = (0, container, key)
            else:
                container = [value]
                stack.append((0, "item", container))
                if is_opener:
                    opener = (0, container, 0)
            root = container
        elif opener is not None and indent > opener[0]:
            _, parent_container, parent_slot = opener
            if kind == "key":
                container = {key: value}
                parent_container[parent_slot] = container
                stack.append((indent, "key", container))
                opener = (indent, container, key) if is_opener else None
            else:
                container = [value]
                parent_container[parent_slot] = container
                stack.append((indent, "item", container))
                opener = (indent, container, 0) if is_opener else None
        else:
            top_indent, top_kind, top_container = stack[-1]
            if indent > top_indent:
                return ("error", lineno, "unexpected indent")
            if indent < top_indent:
                while stack[-1][0] > indent:
                    stack.pop()
                if stack[-1][0] != indent:
                    return ("error", lineno, "inconsistent dedent")
                top_indent, top_kind, top_container = stack[-1]
            if kind != top_kind:
                return ("error", lineno, "mixed block")
            if kind == "key":
                if key in top_container:
                    return ("error", lineno, f"duplicate key '{key}'")
                top_container[key] = value
                opener = (indent, top_container, key) if is_opener else None
            else:
                top_container.append(value)
                opener = (indent, top_container, len(top_container) - 1) if is_opener else None

    return ("ok", root)

import re

_TOKEN_RE = re.compile(r'\[|\]|[^ \t\n\r\[\]]+')
_INT_RE = re.compile(r'-?[0-9]+', re.ASCII)

_OP_INT = 0
_OP_WORD = 1
_OP_QUOT = 2
_OP_DUP = 3
_OP_DROP = 4
_OP_SWAP = 5
_OP_ADD = 6
_OP_SUB = 7
_OP_MUL = 8
_OP_LT = 9
_OP_EQ = 10
_OP_OVER = 11
_OP_ROT = 12
_OP_DIV = 13
_OP_MOD = 14
_OP_IF = 15
_OP_TIMES = 16
_OP_WHILE = 17
_OP_CALL = 18
_OP_DIP = 19
_OP_DEF = 20

_BUILTIN_OPS = {
    'dup': _OP_DUP,
    'drop': _OP_DROP,
    'swap': _OP_SWAP,
    'over': _OP_OVER,
    'rot': _OP_ROT,
    '+': _OP_ADD,
    '-': _OP_SUB,
    '*': _OP_MUL,
    '/': _OP_DIV,
    '%': _OP_MOD,
    '<': _OP_LT,
    '=': _OP_EQ,
    'if': _OP_IF,
    'times': _OP_TIMES,
    'while': _OP_WHILE,
    'call': _OP_CALL,
    'dip': _OP_DIP,
}

_BAD_NAMES = frozenset(_BUILTIN_OPS) | {'[', ']', ':', ';'}

_KIND_SEQ = 0
_KIND_DIP = 1
_KIND_TIMES = 2
_KIND_WHILE_COND = 3
_KIND_WHILE_BODY = 4


def _parse_int(tok: str) -> int:
    try:
        return int(tok)
    except ValueError:
        neg = tok[0] == '-'
        s = tok[1:] if neg else tok
        val = 0
        for j in range(0, len(s), 500):
            chunk = s[j:j + 500]
            val = val * (10 ** len(chunk)) + int(chunk)
        return -val if neg else val


def run_pile(src: str, max_steps: int) -> tuple:
    tokens = _TOKEN_RE.findall(src)
    n = len(tokens)

    # 1. Structure check
    open_stack = []
    i = 0
    while i < n:
        tok = tokens[i]
        if tok == '[':
            open_stack.append(('[', i))
        elif tok == ']':
            if not open_stack or open_stack[-1][0] != '[':
                return ("error", i, "unmatched ]")
            open_stack.pop()
        elif tok == ':':
            if open_stack:
                return ("error", i, "misplaced :")
            if i + 1 >= n:
                return ("error", i, "unclosed :")
            name = tokens[i + 1]
            if name in _BAD_NAMES or _INT_RE.fullmatch(name) is not None:
                return ("error", i + 1, "bad name")
            open_stack.append((':', i))
            i += 1
        elif tok == ';':
            if not open_stack or open_stack[-1][0] != ':':
                return ("error", i, "unmatched ;")
            open_stack.pop()
        i += 1

    if open_stack:
        kind, idx = open_stack[0]
        return ("error", idx, "unclosed [" if kind == '[' else "unclosed :")

    # 2. Iterative compilation
    cur_seq = []
    cur_disp = None
    c_stack = []
    i = 0
    while i < n:
        tok = tokens[i]
        if tok == '[':
            c_stack.append((i, cur_seq, cur_disp, None))
            cur_seq = []
            cur_disp = []
        elif tok == ']':
            open_idx, p_seq, p_disp, _ = c_stack.pop()
            p_seq.append((_OP_QUOT, open_idx, (cur_seq, cur_disp)))
            if p_disp is not None:
                p_disp.append(cur_disp)
            cur_seq = p_seq
            cur_disp = p_disp
        elif tok == ':':
            c_stack.append((i, cur_seq, cur_disp, tokens[i + 1]))
            cur_seq = []
            cur_disp = None
            i += 1
        elif tok == ';':
            open_idx, p_seq, p_disp, name = c_stack.pop()
            p_seq.append((_OP_DEF, open_idx, name, cur_seq))
            cur_seq = p_seq
            cur_disp = p_disp
        else:
            if cur_disp is not None:
                cur_disp.append(tok)
            op = _BUILTIN_OPS.get(tok)
            if op is not None:
                cur_seq.append((op, i))
            elif _INT_RE.fullmatch(tok) is not None:
                cur_seq.append((_OP_INT, i, _parse_int(tok)))
            else:
                cur_seq.append((_OP_WORD, i, tok))
        i += 1

    # 3. Iterative VM execution
    seq = cur_seq
    seq_len = len(seq)
    pc = 0
    stack = []
    defs = {}
    frames = []
    rem_steps = max_steps

    while True:
        while pc == seq_len:
            if not frames:
                return ("ok", [x if type(x) is int else x[1] for x in stack])
            frame = frames[-1]
            kind = frame[0]
            if kind == _KIND_SEQ:
                frames.pop()
                _, seq, pc, seq_len = frame
            elif kind == _KIND_DIP:
                frames.pop()
                stack.append(frame[1])
            elif kind == _KIND_TIMES:
                rem = frame[2] - 1
                if rem > 0:
                    frame[2] = rem
                    seq = frame[1]
                    seq_len = frame[3]
                    pc = 0
                else:
                    frames.pop()
            elif kind == _KIND_WHILE_COND:
                if not stack:
                    return ("error", frame[3], "stack underflow")
                v = stack.pop()
                if type(v) is not int:
                    return ("error", frame[3], "type error")
                if v == 0:
                    frames.pop()
                else:
                    b_seq = frame[2]
                    if b_seq:
                        frame[0] = _KIND_WHILE_BODY
                        seq = b_seq
                        seq_len = len(b_seq)
                        pc = 0
                    else:
                        c_seq = frame[1]
                        if c_seq:
                            seq = c_seq
                            seq_len = len(c_seq)
                            pc = 0
            else:  # _KIND_WHILE_BODY
                c_seq = frame[1]
                frame[0] = _KIND_WHILE_COND
                if c_seq:
                    seq = c_seq
                    seq_len = len(c_seq)
                    pc = 0

        instr = seq[pc]
        pc += 1
        rem_steps -= 1
        if rem_steps < 0:
            return ("error", instr[1], "step limit exceeded")

        op = instr[0]
        if op < 10:
            if op == _OP_INT:
                stack.append(instr[2])
            elif op == _OP_WORD:
                body = defs.get(instr[2])
                if body is None:
                    return ("error", instr[1], f"unknown word '{instr[2]}'")
                if body:
                    if pc < seq_len:
                        frames.append((_KIND_SEQ, seq, pc, seq_len))
                    seq = body
                    seq_len = len(body)
                    pc = 0
            elif op == _OP_QUOT:
                stack.append(instr[2])
            elif op == _OP_DUP:
                if not stack:
                    return ("error", instr[1], "stack underflow")
                stack.append(stack[-1])
            elif op == _OP_DROP:
                if not stack:
                    return ("error", instr[1], "stack underflow")
                stack.pop()
            elif op == _OP_SWAP:
                if len(stack) < 2:
                    return ("error", instr[1], "stack underflow")
                stack[-2], stack[-1] = stack[-1], stack[-2]
            elif op == _OP_ADD:
                if len(stack) < 2:
                    return ("error", instr[1], "stack underflow")
                a = stack[-2]
                b = stack[-1]
                if type(a) is not int or type(b) is not int:
                    return ("error", instr[1], "type error")
                stack.pop()
                stack[-1] = a + b
            elif op == _OP_SUB:
                if len(stack) < 2:
                    return ("error", instr[1], "stack underflow")
                a = stack[-2]
                b = stack[-1]
                if type(a) is not int or type(b) is not int:
                    return ("error", instr[1], "type error")
                stack.pop()
                stack[-1] = a - b
            elif op == _OP_MUL:
                if len(stack) < 2:
                    return ("error", instr[1], "stack underflow")
                a = stack[-2]
                b = stack[-1]
                if type(a) is not int or type(b) is not int:
                    return ("error", instr[1], "type error")
                stack.pop()
                stack[-1] = a * b
            else:  # _OP_LT
                if len(stack) < 2:
                    return ("error", instr[1], "stack underflow")
                a = stack[-2]
                b = stack[-1]
                if type(a) is not int or type(b) is not int:
                    return ("error", instr[1], "type error")
                stack.pop()
                stack[-1] = 1 if a < b else 0
        else:
            if op == _OP_EQ:
                if len(stack) < 2:
                    return ("error", instr[1], "stack underflow")
                a = stack[-2]
                b = stack[-1]
                if type(a) is not int or type(b) is not int:
                    return ("error", instr[1], "type error")
                stack.pop()
                stack[-1] = 1 if a == b else 0
            elif op == _OP_OVER:
                if len(stack) < 2:
                    return ("error", instr[1], "stack underflow")
                stack.append(stack[-2])
            elif op == _OP_ROT:
                if len(stack) < 3:
                    return ("error", instr[1], "stack underflow")
                stack[-3], stack[-2], stack[-1] = stack[-2], stack[-1], stack[-3]
            elif op == _OP_DIV:
                if len(stack) < 2:
                    return ("error", instr[1], "stack underflow")
                a = stack[-2]
                b = stack[-1]
                if type(a) is not int or type(b) is not int:
                    return ("error", instr[1], "type error")
                if b == 0:
                    return ("error", instr[1], "division by zero")
                stack.pop()
                stack[-1] = a // b
            elif op == _OP_MOD:
                if len(stack) < 2:
                    return ("error", instr[1], "stack underflow")
                a = stack[-2]
                b = stack[-1]
                if type(a) is not int or type(b) is not int:
                    return ("error", instr[1], "type error")
                if b == 0:
                    return ("error", instr[1], "division by zero")
                stack.pop()
                stack[-1] = a % b
            elif op == _OP_IF:
                if len(stack) < 3:
                    return ("error", instr[1], "stack underflow")
                c = stack[-3]
                t = stack[-2]
                f = stack[-1]
                if type(c) is not int or type(t) is not tuple or type(f) is not tuple:
                    return ("error", instr[1], "type error")
                del stack[-3:]
                target = t[0] if c != 0 else f[0]
                if target:
                    if pc < seq_len:
                        frames.append((_KIND_SEQ, seq, pc, seq_len))
                    seq = target
                    seq_len = len(target)
                    pc = 0
            elif op == _OP_TIMES:
                if len(stack) < 2:
                    return ("error", instr[1], "stack underflow")
                q = stack[-2]
                cnt = stack[-1]
                if type(q) is not tuple or type(cnt) is not int:
                    return ("error", instr[1], "type error")
                if cnt < 0:
                    return ("error", instr[1], "negative count")
                del stack[-2:]
                q_seq = q[0]
                if cnt > 0 and q_seq:
                    if pc < seq_len:
                        frames.append((_KIND_SEQ, seq, pc, seq_len))
                    q_len = len(q_seq)
                    if cnt > 1:
                        frames.append([_KIND_TIMES, q_seq, cnt, q_len])
                    seq = q_seq
                    seq_len = q_len
                    pc = 0
            elif op == _OP_WHILE:
                if len(stack) < 2:
                    return ("error", instr[1], "stack underflow")
                c = stack[-2]
                b = stack[-1]
                if type(c) is not tuple or type(b) is not tuple:
                    return ("error", instr[1], "type error")
                del stack[-2:]
                c_seq = c[0]
                if pc < seq_len:
                    frames.append((_KIND_SEQ, seq, pc, seq_len))
                frames.append([_KIND_WHILE_COND, c_seq, b[0], instr[1]])
                seq = c_seq
                seq_len = len(c_seq)
                pc = 0
            elif op == _OP_CALL:
                if not stack:
                    return ("error", instr[1], "stack underflow")
                q = stack[-1]
                if type(q) is not tuple:
                    return ("error", instr[1], "type error")
                stack.pop()
                q_seq = q[0]
                if q_seq:
                    if pc < seq_len:
                        frames.append((_KIND_SEQ, seq, pc, seq_len))
                    seq = q_seq
                    seq_len = len(q_seq)
                    pc = 0
            elif op == _OP_DIP:
                if len(stack) < 2:
                    return ("error", instr[1], "stack underflow")
                a = stack[-2]
                q = stack[-1]
                if type(q) is not tuple:
                    return ("error", instr[1], "type error")
                del stack[-2:]
                q_seq = q[0]
                if q_seq:
                    if pc < seq_len:
                        frames.append((_KIND_SEQ, seq, pc, seq_len))
                    frames.append((_KIND_DIP, a))
                    seq = q_seq
                    seq_len = len(q_seq)
                    pc = 0
                else:
                    stack.append(a)
            else:  # _OP_DEF
                defs[instr[2]] = instr[3]

_TOK_END = 0
_TOK_FIELD = 1
_TOK_INT = 2
_TOK_STR = 3
_TOK_OP = 4
_TOK_LPAREN = 5
_TOK_RPAREN = 6
_TOK_LBRACK = 7
_TOK_RBRACK = 8
_TOK_COMMA = 9
_TOK_AND = 10
_TOK_OR = 11
_TOK_NOT = 12
_TOK_IN = 13
_TOK_HAS = 14

_OP_HAS = 0
_OP_EQ = 1
_OP_NE = 2
_OP_LT = 3
_OP_LE = 4
_OP_GT = 5
_OP_GE = 6
_OP_IN = 7
_OP_NOT = 8
_OP_MIN = 9
_OP_MAX = 10
_OP_JIF = 11
_OP_JIT = 12

_KEYWORDS = {
    "and": _TOK_AND,
    "or": _TOK_OR,
    "not": _TOK_NOT,
    "in": _TOK_IN,
    "has": _TOK_HAS,
}

_MISSING = object()


def _parse_int(s: str) -> int:
    if len(s) <= 4000:
        return int(s)
    neg = s[0] == "-"
    start = 1 if neg else 0
    val = 0
    n = len(s)
    for i in range(start, n, 1000):
        chunk = s[i:i + 1000]
        val = val * (10 ** len(chunk)) + int(chunk)
    return -val if neg else val


def _lex(query: str):
    tokens = []
    n = len(query)
    i = 0
    while i < n:
        c = query[i]
        if c == " " or c == "\t" or c == "\n":
            i += 1
        elif c == "(":
            tokens.append((_TOK_LPAREN, i, "(", None))
            i += 1
        elif c == ")":
            tokens.append((_TOK_RPAREN, i, ")", None))
            i += 1
        elif c == "[":
            tokens.append((_TOK_LBRACK, i, "[", None))
            i += 1
        elif c == "]":
            tokens.append((_TOK_RBRACK, i, "]", None))
            i += 1
        elif c == ",":
            tokens.append((_TOK_COMMA, i, ",", None))
            i += 1
        elif c == "=":
            tokens.append((_TOK_OP, i, "=", _OP_EQ))
            i += 1
        elif c == "!":
            if i + 1 < n and query[i + 1] == "=":
                tokens.append((_TOK_OP, i, "!=", _OP_NE))
                i += 2
            else:
                return None, ("error", i, "unexpected character '!'")
        elif c == "<":
            if i + 1 < n and query[i + 1] == "=":
                tokens.append((_TOK_OP, i, "<=", _OP_LE))
                i += 2
            else:
                tokens.append((_TOK_OP, i, "<", _OP_LT))
                i += 1
        elif c == ">":
            if i + 1 < n and query[i + 1] == "=":
                tokens.append((_TOK_OP, i, ">=", _OP_GE))
                i += 2
            else:
                tokens.append((_TOK_OP, i, ">", _OP_GT))
                i += 1
        elif c == "-":
            if i + 1 < n and "0" <= query[i + 1] <= "9":
                j = i + 2
                while j < n and "0" <= query[j] <= "9":
                    j += 1
                text = query[i:j]
                tokens.append((_TOK_INT, i, text, _parse_int(text)))
                i = j
            else:
                return None, ("error", i, "unexpected character '-'")
        elif "0" <= c <= "9":
            j = i + 1
            while j < n and "0" <= query[j] <= "9":
                j += 1
            text = query[i:j]
            tokens.append((_TOK_INT, i, text, _parse_int(text)))
            i = j
        elif c == '"':
            start = i
            i += 1
            chunks = []
            seg_start = i
            while i < n:
                ch = query[i]
                if ch == '"':
                    if chunks:
                        chunks.append(query[seg_start:i])
                        val = "".join(chunks)
                    else:
                        val = query[seg_start:i]
                    tokens.append((_TOK_STR, start, query[start:i + 1], val))
                    i += 1
                    break
                elif ch == "\\":
                    if i + 1 >= n:
                        return None, ("error", i, "bad escape")
                    nxt = query[i + 1]
                    if nxt != '"' and nxt != "\\":
                        return None, ("error", i, "bad escape")
                    chunks.append(query[seg_start:i])
                    chunks.append(nxt)
                    i += 2
                    seg_start = i
                else:
                    i += 1
            else:
                return None, ("error", start, "unterminated string")
        elif ("A" <= c <= "Z") or ("a" <= c <= "z") or c == "_":
            j = i + 1
            while j < n:
                ch = query[j]
                if (
                    ("A" <= ch <= "Z")
                    or ("a" <= ch <= "z")
                    or ("0" <= ch <= "9")
                    or ch == "_"
                    or ch == "."
                ):
                    j += 1
                else:
                    break
            text = query[i:j]
            kw = _KEYWORDS.get(text)
            if kw is not None:
                tokens.append((kw, i, text, None))
            else:
                tokens.append((_TOK_FIELD, i, text, None))
            i = j
        else:
            return None, ("error", i, f"unexpected character '{c}'")

    tokens.append((_TOK_END, n, "", None))
    return tokens, None


def _parse_err(tok):
    if tok[0] == _TOK_END:
        return ("error", tok[1], "unexpected end of input")
    return ("error", tok[1], f"unexpected token '{tok[2]}'")


def _compile(tokens):
    code = []
    stack = []
    not_count = 0
    and_jumps = []
    or_jumps = []
    in_and = False
    in_or = False
    ti = 0

    while True:
        tok = tokens[ti]
        ttype = tok[0]
        while ttype == _TOK_NOT:
            not_count += 1
            ti += 1
            tok = tokens[ti]
            ttype = tok[0]

        if ttype == _TOK_LPAREN:
            stack.append((not_count, and_jumps, or_jumps, in_and, in_or))
            not_count = 0
            and_jumps = []
            or_jumps = []
            in_and = False
            in_or = False
            ti += 1
            continue

        elif ttype == _TOK_HAS:
            ti += 1
            tok2 = tokens[ti]
            if tok2[0] != _TOK_FIELD:
                return None, _parse_err(tok2)
            code.append((_OP_HAS, tok2[2]))
            ti += 1

        elif ttype == _TOK_FIELD:
            field = tok[2]
            ti += 1
            tok2 = tokens[ti]
            t2type = tok2[0]
            if t2type == _TOK_OP:
                op_code = tok2[3]
                ti += 1
                tok3 = tokens[ti]
                t3type = tok3[0]
                if t3type != _TOK_INT and t3type != _TOK_STR:
                    return None, _parse_err(tok3)
                lit = tok3[3]
                if op_code == _OP_EQ or op_code == _OP_NE:
                    code.append((op_code, field, lit))
                else:
                    code.append((op_code, field, lit, t3type == _TOK_INT))
                ti += 1
            elif t2type == _TOK_IN:
                ti += 1
                tok3 = tokens[ti]
                if tok3[0] != _TOK_LBRACK:
                    return None, _parse_err(tok3)
                ti += 1
                tok4 = tokens[ti]
                if tok4[0] != _TOK_INT and tok4[0] != _TOK_STR:
                    return None, _parse_err(tok4)
                vals = [tok4[3]]
                ti += 1
                while True:
                    tok5 = tokens[ti]
                    t5type = tok5[0]
                    if t5type == _TOK_COMMA:
                        ti += 1
                        tok6 = tokens[ti]
                        if tok6[0] != _TOK_INT and tok6[0] != _TOK_STR:
                            return None, _parse_err(tok6)
                        vals.append(tok6[3])
                        ti += 1
                    elif t5type == _TOK_RBRACK:
                        ti += 1
                        break
                    else:
                        return None, _parse_err(tok5)
                code.append((_OP_IN, field, frozenset(vals)))
            else:
                return None, _parse_err(tok2)
        else:
            return None, _parse_err(tok)

        while True:
            if not_count & 1:
                code.append((_OP_NOT,))
                not_count = 0
            if in_and:
                code.append((_OP_MIN,))

            tok = tokens[ti]
            ttype = tok[0]
            if ttype == _TOK_AND:
                in_and = True
                and_jumps.append(len(code))
                code.append(None)
                not_count = 0
                ti += 1
                break
            elif ttype == _TOK_OR:
                if and_jumps:
                    target = len(code)
                    for j in and_jumps:
                        code[j] = (_OP_JIF, target)
                    and_jumps.clear()
                    in_and = False
                if in_or:
                    code.append((_OP_MAX,))
                in_or = True
                or_jumps.append(len(code))
                code.append(None)
                not_count = 0
                ti += 1
                break
            elif ttype == _TOK_RPAREN and stack:
                if and_jumps:
                    target = len(code)
                    for j in and_jumps:
                        code[j] = (_OP_JIF, target)
                    and_jumps.clear()
                if in_or:
                    code.append((_OP_MAX,))
                if or_jumps:
                    target = len(code)
                    for j in or_jumps:
                        code[j] = (_OP_JIT, target)
                    or_jumps.clear()
                not_count, and_jumps, or_jumps, in_and, in_or = stack.pop()
                ti += 1
            elif ttype == _TOK_END and not stack:
                if and_jumps:
                    target = len(code)
                    for j in and_jumps:
                        code[j] = (_OP_JIF, target)
                    and_jumps.clear()
                if in_or:
                    code.append((_OP_MAX,))
                if or_jumps:
                    target = len(code)
                    for j in or_jumps:
                        code[j] = (_OP_JIT, target)
                    or_jumps.clear()
                return code, None
            else:
                return None, _parse_err(tok)


def filter_records(query: str, records: list[dict]) -> tuple:
    tokens, err = _lex(query)
    if err is not None:
        return err
    code, err = _compile(tokens)
    if err is not None:
        return err

    n_code = len(code)
    matched = []
    for idx, rec in enumerate(records):
        stack = []
        pc = 0
        while pc < n_code:
            ins = code[pc]
            op = ins[0]
            if op == _OP_EQ:
                val = rec.get(ins[1], _MISSING)
                if val is _MISSING:
                    stack.append(1)
                else:
                    stack.append(2 if val == ins[2] else 0)
            elif op == _OP_NE:
                val = rec.get(ins[1], _MISSING)
                if val is _MISSING:
                    stack.append(1)
                else:
                    stack.append(2 if val != ins[2] else 0)
            elif op == _OP_LT:
                val = rec.get(ins[1], _MISSING)
                if val is _MISSING or (type(val) is int) != ins[3]:
                    stack.append(1)
                else:
                    stack.append(2 if val < ins[2] else 0)
            elif op == _OP_LE:
                val = rec.get(ins[1], _MISSING)
                if val is _MISSING or (type(val) is int) != ins[3]:
                    stack.append(1)
                else:
                    stack.append(2 if val <= ins[2] else 0)
            elif op == _OP_GT:
                val = rec.get(ins[1], _MISSING)
                if val is _MISSING or (type(val) is int) != ins[3]:
                    stack.append(1)
                else:
                    stack.append(2 if val > ins[2] else 0)
            elif op == _OP_GE:
                val = rec.get(ins[1], _MISSING)
                if val is _MISSING or (type(val) is int) != ins[3]:
                    stack.append(1)
                else:
                    stack.append(2 if val >= ins[2] else 0)
            elif op == _OP_HAS:
                stack.append(2 if ins[1] in rec else 0)
            elif op == _OP_IN:
                val = rec.get(ins[1], _MISSING)
                if val is _MISSING:
                    stack.append(1)
                else:
                    stack.append(2 if val in ins[2] else 0)
            elif op == _OP_NOT:
                stack[-1] = 2 - stack[-1]
            elif op == _OP_MIN:
                b = stack.pop()
                if b < stack[-1]:
                    stack[-1] = b
            elif op == _OP_MAX:
                b = stack.pop()
                if b > stack[-1]:
                    stack[-1] = b
            elif op == _OP_JIF:
                if stack[-1] == 0:
                    pc = ins[1]
                    continue
            elif op == _OP_JIT:
                if stack[-1] == 2:
                    pc = ins[1]
                    continue
            pc += 1
        if stack[0] == 2:
            matched.append(idx)
    return ("ok", matched)

import re

_TOK_INT = 1
_TOK_NAME = 2
_TOK_CMPOP = 3
_TOK_OP = 4
_TOK_INVALID = 5
_TOK_END = 6

_TOKEN_RE = re.compile(
    r" +|([0-9]+)|([a-z_][a-z0-9_]*)|(<=|>=|==|!=|<|>)|([+\-*/%^()?:])|(.)",
    re.DOTALL | re.ASCII,
)

# Parser states
_ST_COND = 0
_ST_COND_Q = 1
_ST_COND_COLON = 2
_ST_COND_END = 3
_ST_CMP = 4
_ST_CMP_OP = 5
_ST_CMP_EMIT = 6
_ST_SUM = 7
_ST_SUM_LOOP = 8
_ST_SUM_EMIT = 9
_ST_TERM = 10
_ST_TERM_LOOP = 11
_ST_TERM_EMIT = 12
_ST_UNARY = 13
_ST_UNARY_EMIT = 14
_ST_POWER = 15
_ST_POWER_OP = 16
_ST_POWER_EMIT = 17
_ST_ATOM = 18
_ST_RPAREN = 19
_ST_END = 20

# VM opcodes
_OP_CONST = 0
_OP_VAR = 1
_OP_NEG = 2
_OP_ADD = 3
_OP_SUB = 4
_OP_MUL = 5
_OP_DIV = 6
_OP_MOD = 7
_OP_POW = 8
_OP_LT = 9
_OP_LE = 10
_OP_GT = 11
_OP_GE = 12
_OP_EQ = 13
_OP_NE = 14
_OP_JIZ = 15
_OP_JUMP = 16

_CMP_TO_OP = {
    "<": _OP_LT,
    "<=": _OP_LE,
    ">": _OP_GT,
    ">=": _OP_GE,
    "==": _OP_EQ,
    "!=": _OP_NE,
}


def _syntax_error(tok_kind: int, tok_pos: int, tok_text: str) -> tuple:
    if tok_kind == _TOK_END:
        return ("error", tok_pos, "unexpected end of input")
    if tok_kind == _TOK_INVALID:
        return ("error", tok_pos, f"unexpected character '{tok_text}'")
    return ("error", tok_pos, f"unexpected token '{tok_text}'")


def _parse_big_int(s: str) -> int:
    # Divide-and-conquer avoids Python 3.11+'s int_max_str_digits (4300) limit.
    n = len(s)
    if n <= 4000:
        return int(s)
    mid = n >> 1
    return _parse_big_int(s[:mid]) * (10 ** (n - mid)) + _parse_big_int(s[mid:])


def evaluate(src: str, env: dict) -> tuple:
    it = _TOKEN_RE.finditer(src)
    len_src = len(src)

    def next_tok():
        for m in it:
            idx = m.lastindex
            if idx is not None:
                return idx, m.start(), m.group(idx)
        return _TOK_END, len_src, ""

    tok_kind, tok_pos, tok_text = next_tok()

    # Phase 1: Iterative LL(1) recursive-descent parser -> bytecode
    stack = [_ST_END]
    state = _ST_COND
    payload = None
    ops = []
    args = []

    while True:
        if state == _ST_COND:
            stack.append(_ST_COND_Q)
            state = _ST_CMP
            continue
        elif state == _ST_CMP:
            stack.append(_ST_CMP_OP)
            state = _ST_SUM
            continue
        elif state == _ST_SUM:
            stack.append(_ST_SUM_LOOP)
            state = _ST_TERM
            continue
        elif state == _ST_TERM:
            stack.append(_ST_TERM_LOOP)
            state = _ST_UNARY
            continue
        elif state == _ST_UNARY:
            neg = 0
            while tok_kind == _TOK_OP and tok_text == "-":
                neg ^= 1
                tok_kind, tok_pos, tok_text = next_tok()
            if neg:
                stack.append(_ST_UNARY_EMIT)
            state = _ST_POWER
            continue
        elif state == _ST_POWER:
            stack.append(_ST_POWER_OP)
            state = _ST_ATOM
            continue
        elif state == _ST_ATOM:
            if tok_kind == _TOK_INT:
                ops.append(_OP_CONST)
                args.append(tok_text)
                tok_kind, tok_pos, tok_text = next_tok()
            elif tok_kind == _TOK_NAME:
                ops.append(_OP_VAR)
                args.append((tok_text, tok_pos))
                tok_kind, tok_pos, tok_text = next_tok()
            elif tok_kind == _TOK_OP and tok_text == "(":
                tok_kind, tok_pos, tok_text = next_tok()
                stack.append(_ST_RPAREN)
                state = _ST_COND
                continue
            else:
                return _syntax_error(tok_kind, tok_pos, tok_text)
        elif state == _ST_POWER_OP:
            if tok_kind == _TOK_OP and tok_text == "^":
                pos = tok_pos
                tok_kind, tok_pos, tok_text = next_tok()
                stack.append((_ST_POWER_EMIT, pos))
                state = _ST_UNARY
                continue
        elif state == _ST_POWER_EMIT:
            ops.append(_OP_POW)
            args.append(payload)
        elif state == _ST_UNARY_EMIT:
            ops.append(_OP_NEG)
            args.append(None)
        elif state == _ST_TERM_LOOP:
            if tok_kind == _TOK_OP and (tok_text == "*" or tok_text == "/" or tok_text == "%"):
                op = tok_text
                pos = tok_pos
                tok_kind, tok_pos, tok_text = next_tok()
                stack.append((_ST_TERM_EMIT, (op, pos)))
                state = _ST_UNARY
                continue
        elif state == _ST_TERM_EMIT:
            op, pos = payload
            if op == "*":
                ops.append(_OP_MUL)
                args.append(None)
            elif op == "/":
                ops.append(_OP_DIV)
                args.append(pos)
            else:
                ops.append(_OP_MOD)
                args.append(pos)
            state = _ST_TERM_LOOP
            continue
        elif state == _ST_SUM_LOOP:
            if tok_kind == _TOK_OP and (tok_text == "+" or tok_text == "-"):
                op = tok_text
                tok_kind, tok_pos, tok_text = next_tok()
                stack.append((_ST_SUM_EMIT, op))
                state = _ST_TERM
                continue
        elif state == _ST_SUM_EMIT:
            ops.append(_OP_ADD if payload == "+" else _OP_SUB)
            args.append(None)
            state = _ST_SUM_LOOP
            continue
        elif state == _ST_CMP_OP:
            if tok_kind == _TOK_CMPOP:
                op = tok_text
                tok_kind, tok_pos, tok_text = next_tok()
                stack.append((_ST_CMP_EMIT, op))
                state = _ST_SUM
                continue
        elif state == _ST_CMP_EMIT:
            ops.append(_CMP_TO_OP[payload])
            args.append(None)
        elif state == _ST_COND_Q:
            if tok_kind == _TOK_OP and tok_text == "?":
                tok_kind, tok_pos, tok_text = next_tok()
                jiz_idx = len(ops)
                ops.append(_OP_JIZ)
                args.append(0)
                stack.append((_ST_COND_COLON, jiz_idx))
                state = _ST_COND
                continue
        elif state == _ST_COND_COLON:
            if tok_kind != _TOK_OP or tok_text != ":":
                return _syntax_error(tok_kind, tok_pos, tok_text)
            tok_kind, tok_pos, tok_text = next_tok()
            jmp_idx = len(ops)
            ops.append(_OP_JUMP)
            args.append(0)
            args[payload] = len(ops)
            stack.append((_ST_COND_END, jmp_idx))
            state = _ST_COND
            continue
        elif state == _ST_COND_END:
            args[payload] = len(ops)
        elif state == _ST_RPAREN:
            if tok_kind != _TOK_OP or tok_text != ")":
                return _syntax_error(tok_kind, tok_pos, tok_text)
            tok_kind, tok_pos, tok_text = next_tok()
        elif state == _ST_END:
            if tok_kind != _TOK_END:
                return _syntax_error(tok_kind, tok_pos, tok_text)
            break

        item = stack.pop()
        if type(item) is int:
            state = item
        else:
            state, payload = item

    # Phase 2: Iterative stack-based bytecode VM evaluation
    vstack = []
    pc = 0
    num_ops = len(ops)

    while pc < num_ops:
        op = ops[pc]
        if op == _OP_CONST:
            raw = args[pc]
            vstack.append(int(raw) if len(raw) <= 4000 else _parse_big_int(raw))
            pc += 1
        elif op == _OP_VAR:
            name, pos = args[pc]
            val = env.get(name)
            if val is None:
                return ("error", pos, f"unknown name '{name}'")
            vstack.append(val)
            pc += 1
        elif op == _OP_NEG:
            vstack[-1] = -vstack[-1]
            pc += 1
        elif op == _OP_ADD:
            b = vstack.pop()
            vstack[-1] += b
            pc += 1
        elif op == _OP_SUB:
            b = vstack.pop()
            vstack[-1] -= b
            pc += 1
        elif op == _OP_MUL:
            b = vstack.pop()
            vstack[-1] *= b
            pc += 1
        elif op == _OP_DIV:
            b = vstack.pop()
            if b == 0:
                return ("error", args[pc], "division by zero")
            vstack[-1] //= b
            pc += 1
        elif op == _OP_MOD:
            b = vstack.pop()
            if b == 0:
                return ("error", args[pc], "division by zero")
            vstack[-1] %= b
            pc += 1
        elif op == _OP_POW:
            b = vstack.pop()
            if b < 0:
                return ("error", args[pc], "negative exponent")
            if b > 256:
                return ("error", args[pc], "exponent too large")
            vstack[-1] **= b
            pc += 1
        elif op == _OP_LT:
            b = vstack.pop()
            vstack[-1] = 1 if vstack[-1] < b else 0
            pc += 1
        elif op == _OP_LE:
            b = vstack.pop()
            vstack[-1] = 1 if vstack[-1] <= b else 0
            pc += 1
        elif op == _OP_GT:
            b = vstack.pop()
            vstack[-1] = 1 if vstack[-1] > b else 0
            pc += 1
        elif op == _OP_GE:
            b = vstack.pop()
            vstack[-1] = 1 if vstack[-1] >= b else 0
            pc += 1
        elif op == _OP_EQ:
            b = vstack.pop()
            vstack[-1] = 1 if vstack[-1] == b else 0
            pc += 1
        elif op == _OP_NE:
            b = vstack.pop()
            vstack[-1] = 1 if vstack[-1] != b else 0
            pc += 1
        elif op == _OP_JIZ:
            if vstack.pop() == 0:
                pc = args[pc]
            else:
                pc += 1
        elif op == _OP_JUMP:
            pc = args[pc]

    return ("ok", vstack[0])

import math
import re

_PRINCIPAL_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,2})?")
_RATE_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,6})?")


def _format_cents(cents: int) -> str:
    dollars, rem = divmod(cents, 100)
    return f"{dollars}.{rem:02d}"


def amortize(principal: str, annual_rate_pct: str, months: int) -> list[tuple[str, str, str]]:
    if not isinstance(principal, str) or _PRINCIPAL_RE.fullmatch(principal) is None:
        raise ValueError("Invalid principal format")
    if "." in principal:
        int_part, frac_part = principal.split(".")
        p_cents = int(int_part) * 100 + int(frac_part.ljust(2, "0"))
    else:
        p_cents = int(principal) * 100
    if p_cents <= 0:
        raise ValueError("principal must be > 0")

    if not isinstance(annual_rate_pct, str) or _RATE_RE.fullmatch(annual_rate_pct) is None:
        raise ValueError("Invalid annual_rate_pct format")
    if "." in annual_rate_pct:
        int_part, frac_part = annual_rate_pct.split(".")
        rate_micro = int(int_part) * 1_000_000 + int(frac_part.ljust(6, "0"))
    else:
        rate_micro = int(annual_rate_pct) * 1_000_000
    if rate_micro > 100_000_000:
        raise ValueError("annual_rate_pct must be <= 100")

    if not isinstance(months, int) or isinstance(months, bool) or not (1 <= months <= 1200):
        raise ValueError("months must be an int with 1 <= months <= 1200")

    if rate_micro == 0:
        pay_cents = (p_cents + months - 1) // months
        a, b = 0, 1
    else:
        den_base = 1_200_000_000
        g = math.gcd(rate_micro, den_base)
        a = rate_micro // g
        b = den_base // g
        # A = P * (a/b) / (1 - (b/(b+a))^n) = P * a * (b+a)^n / (b * ((b+a)^n - b^n))
        u = pow(b + a, months)
        v = pow(b, months)
        num_a = p_cents * a * u
        den_a = b * (u - v)
        pay_cents = (num_a + den_a - 1) // den_a

    schedule: list[tuple[str, str, str]] = []
    bal_cents = p_cents
    for t in range(1, months + 1):
        if a == 0:
            interest_cents = 0
        else:
            q, r = divmod(bal_cents * a, b)
            twice_r = r * 2
            if twice_r > b or (twice_r == b and (q & 1)):
                interest_cents = q + 1
            else:
                interest_cents = q

        if t == months or bal_cents + interest_cents <= pay_cents:
            row_pay = bal_cents + interest_cents
            schedule.append((_format_cents(row_pay), _format_cents(interest_cents), "0.00"))
            break

        new_bal = bal_cents - (pay_cents - interest_cents)
        schedule.append((_format_cents(pay_cents), _format_cents(interest_cents), _format_cents(new_bal)))
        bal_cents = new_bal

    return schedule

import math

_DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"
_DIGIT_VAL = {ch: i for i, ch in enumerate(_DIGITS)}
_BASE_CACHE = {}


def _get_base_info(base: int):
    info = _BASE_CACHE.get(base)
    if info is not None:
        return info
    # Choose largest d such that base**d <= 4096
    d = 1
    b_d = base
    while b_d * base <= 4096:
        b_d *= base
        d += 1
    table = list(_DIGITS[:base])
    for _ in range(1, d):
        table = [prefix + ch for prefix in table for ch in _DIGITS[:base]]
    b_2d = b_d * b_d
    b_4d = b_2d * b_2d
    b_8d = b_4d * b_4d
    info = (d, b_d, b_2d, b_4d, b_8d, table)
    _BASE_CACHE[base] = info
    return info


def _format_int(num: int, base: int) -> str:
    if num == 0:
        return "0"
    if num < base:
        return _DIGITS[num]
    _, b_d, _, _, _, table = _get_base_info(base)
    parts = []
    while num >= b_d:
        num, r = divmod(num, b_d)
        parts.append(table[r])
    parts.append(table[num].lstrip("0"))
    parts.reverse()
    return "".join(parts)


def format_base(p: int, q: int, base: int, k: int) -> str:
    if q == 0 or base < 2 or base > 36 or k < 0:
        raise ValueError("Invalid arguments: require q != 0, 2 <= base <= 36, k >= 0")

    if p == 0:
        return "0"

    neg = (p < 0) != (q < 0)
    P = abs(p)
    Q = abs(q)
    g = math.gcd(P, Q)
    if g > 1:
        P //= g
        Q //= g

    # Fast exact path for small k
    if k < 64:
        base_k = base ** k
        N, rem = divmod(P * base_k, Q)
        cmp = 2 * rem - Q
        if cmp > 0 or (cmp == 0 and (N & 1)):
            N += 1
        if N == 0:
            return "0"
        I, F = divmod(N, base_k)
        int_str = _format_int(I, base)
        if F == 0:
            return "-" + int_str if neg else int_str
        frac_str = _format_int(F, base).rjust(k, "0").rstrip("0")
        res = f"{int_str}.{frac_str}"
        return "-" + res if neg else res

    # Large k: chunked left-to-right long division of R / Q
    I0, r = divmod(P, Q)
    if r == 0:
        int_str = _format_int(I0, base)
        return "-" + int_str if neg else int_str

    d, b_d, b_2d, b_4d, b_8d, table = _get_base_info(base)
    chunk_digits = 8 * d
    q_chunks, rem_k = divmod(k, chunk_digits)

    is_even_base = (base & 1) == 0
    f_parity = 0
    last_parity = 0

    parts = []
    parts_extend = parts.extend

    for _ in range(q_chunks):
        chunk, r = divmod(r * b_8d, Q)
        if is_even_base:
            last_parity = chunk & 1
        else:
            f_parity ^= chunk & 1
        q4, r4 = divmod(chunk, b_4d)
        q2a, q2b = divmod(q4, b_2d)
        q2c, q2d = divmod(r4, b_2d)
        d7, d6 = divmod(q2a, b_d)
        d5, d4 = divmod(q2b, b_d)
        d3, d2 = divmod(q2c, b_d)
        d1, d0 = divmod(q2d, b_d)
        parts_extend((
            table[d7], table[d6], table[d5], table[d4],
            table[d3], table[d2], table[d1], table[d0],
        ))
        if r == 0:
            break
    else:
        if rem_k > 0:
            chunk, r = divmod(r * (base ** rem_k), Q)
            if is_even_base:
                last_parity = chunk & 1
            else:
                f_parity ^= chunk & 1
            if chunk == 0:
                parts.append("0" * rem_k)
            else:
                rem_s = _format_int(chunk, base)
                if len(rem_s) < rem_k:
                    parts.append("0" * (rem_k - len(rem_s)))
                parts.append(rem_s)

    frac_str = "".join(parts)

    if r == 0:
        round_up = False
    else:
        cmp = 2 * r - Q
        if cmp > 0:
            round_up = True
        elif cmp < 0:
            round_up = False
        else:
            n0_parity = last_parity if is_even_base else ((I0 & 1) ^ f_parity)
            round_up = bool(n0_parity)

    if round_up:
        max_ch = _DIGITS[base - 1]
        trimmed = frac_str.rstrip(max_ch)
        if not trimmed:
            I = I0 + 1
            frac_part = ""
        else:
            I = I0
            frac_part = trimmed[:-1] + _DIGITS[_DIGIT_VAL[trimmed[-1]] + 1]
    else:
        I = I0
        frac_part = frac_str.rstrip("0")

    if I == 0 and not frac_part:
        return "0"

    int_str = _format_int(I, base)
    res = f"{int_str}.{frac_part}" if frac_part else int_str
    return "-" + res if neg else res

_FIVE_POW_25 = 5 ** 25
_Q_INF = 4095 << 29  # 65520 * 2**25


def decimal_to_half_bits(s: str) -> int:
    if not isinstance(s, str) or not s:
        raise ValueError("invalid decimal literal")

    i = 0
    neg = False
    c0 = s[0]
    if c0 == "-":
        neg = True
        i = 1
    elif c0 == "+":
        i = 1

    e_pos = s.find("e", i)
    upper_e_pos = s.find("E", i)
    if e_pos == -1:
        e_pos = upper_e_pos
    elif upper_e_pos != -1 and upper_e_pos < e_pos:
        e_pos = upper_e_pos

    if e_pos == -1:
        mant_str = s[i:]
        exp_str = None
    else:
        mant_str = s[i:e_pos]
        exp_str = s[e_pos + 1 :]

    if exp_str is not None:
        if not exp_str:
            raise ValueError("invalid exponent in decimal literal")
        exp_neg = False
        j = 0
        ec0 = exp_str[0]
        if ec0 == "-":
            exp_neg = True
            j = 1
        elif ec0 == "+":
            j = 1
        exp_digits = exp_str[j:]
        if not (exp_digits.isascii() and exp_digits.isdigit()):
            raise ValueError("invalid exponent in decimal literal")
    else:
        exp_neg = False
        exp_digits = ""

    dot_pos = mant_str.find(".")
    if dot_pos == -1:
        int_str = mant_str
        frac_str = ""
        if not (int_str.isascii() and int_str.isdigit()):
            raise ValueError("invalid mantissa in decimal literal")
    else:
        int_str = mant_str[:dot_pos]
        frac_str = mant_str[dot_pos + 1 :]
        if int_str:
            if not (int_str.isascii() and int_str.isdigit()):
                raise ValueError("invalid integer part in decimal literal")
            if frac_str and not (frac_str.isascii() and frac_str.isdigit()):
                raise ValueError("invalid fractional part in decimal literal")
        else:
            if not (frac_str.isascii() and frac_str.isdigit()):
                raise ValueError("invalid fractional part in decimal literal")

    int_stripped = int_str.lstrip("0")
    if int_stripped:
        base_exp = len(int_stripped) - 1
        sig = int_stripped + frac_str
    else:
        frac_stripped = frac_str.lstrip("0")
        if not frac_stripped:
            return 0x8000 if neg else 0x0000
        leading_zeros = len(frac_str) - len(frac_stripped)
        base_exp = -(leading_zeros + 1)
        sig = frac_stripped

    if exp_digits:
        exp_d = exp_digits.lstrip("0")
        if not exp_d:
            exp = 0
        elif len(exp_d) > max(10, len(str(len(s))) + 2):
            if exp_neg:
                return 0x8000 if neg else 0x0000
            return 0xFC00 if neg else 0x7C00
        else:
            exp = int(exp_d)
            if exp_neg:
                exp = -exp
    else:
        exp = 0

    msd_exp = base_exp + exp
    if msd_exp >= 5:
        return 0xFC00 if neg else 0x7C00
    if msd_exp <= -9:
        return 0x8000 if neg else 0x0000

    # All binary16 values and tie midpoints are integer multiples of 2**-25,
    # which terminate in decimal within 25 places after the decimal point.
    # Split v * 10**25 into floor(v * 10**25) and a sticky flag for any tail.
    k = msd_exp + 26
    m = len(sig)
    if m <= k:
        x0 = int(sig) * (10 ** (k - m))
        sticky = False
    else:
        x0 = int(sig[:k])
        sticky = sig[k:].count("0") != (m - k)

    # q = floor(v * 2**25); exact iff v * 2**25 == q
    q, r = divmod(x0, _FIVE_POW_25)
    if q >= _Q_INF:
        return 0xFC00 if neg else 0x7C00

    exact = r == 0 and not sticky

    if q < 2048:
        e = 0
        f = q >> 1
        rem = q & 1
        half = 1
    else:
        b = q.bit_length()
        e = b - 11
        step = 1 << e
        half = step >> 1
        offset = q - (1 << (b - 1))
        f = offset >> e
        rem = offset & (step - 1)

    if rem > half or (rem == half and (not exact or (f & 1))):
        bits = (e << 10) + f + 1
    else:
        bits = (e << 10) + f

    if neg:
        bits |= 0x8000
    return bits

from collections import OrderedDict
import heapq


def run_cache(capacity, ops):
    if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 1:
        raise ValueError("capacity must be a positive int")

    store = OrderedDict()  # key -> [value, token]; oldest use first
    expiry_heap = []       # min-heap of (expires_at, token, key)
    out = []
    last_t = None
    next_token = 0
    heappush = heapq.heappush
    heappop = heapq.heappop

    def purge_expired(t):
        while expiry_heap and expiry_heap[0][0] <= t:
            _, token, key = heappop(expiry_heap)
            entry = store.get(key)
            if entry is not None and entry[1] == token:
                del store[key]

    for op in ops:
        kind, t = op[0], op[1]
        if last_t is not None and t < last_t:
            raise ValueError("operations must have non-decreasing timestamps")
        last_t = t

        if kind == "put":
            _, _, key, value, ttl = op
            if ttl is not None and (not isinstance(ttl, int) or isinstance(ttl, bool) or ttl < 1):
                raise ValueError("ttl must be None or a positive int")
            purge_expired(t)
            next_token += 1
            token = next_token
            entry = store.get(key)
            if entry is not None:
                entry[0] = value
                entry[1] = token
                store.move_to_end(key)
            else:
                if len(store) >= capacity:
                    store.popitem(last=False)
                store[key] = [value, token]
            if ttl is not None:
                heappush(expiry_heap, (t + ttl, token, key))

        elif kind == "get":
            key = op[2]
            purge_expired(t)
            entry = store.get(key)
            if entry is None:
                out.append(None)
            else:
                store.move_to_end(key)
                out.append(entry[0])

        elif kind == "size":
            purge_expired(t)
            out.append(len(store))

        else:
            raise ValueError("unknown operation %r" % (kind,))

    return out

import heapq


def window_medians(readings, k):
    if isinstance(k, bool) or not isinstance(k, int) or k < 1:
        raise ValueError("k must be a positive int")

    low = []    # max-heap via negation: the smaller half, its top is the median
    high = []   # min-heap: the larger half
    delayed = {}  # value -> pending lazy deletions
    low_size = 0
    high_size = 0
    out = []

    heappush = heapq.heappush
    heappop = heapq.heappop

    def prune(heap, sign):
        # drop deleted values sitting on top of a heap
        while heap:
            v = sign * heap[0]
            c = delayed.get(v)
            if not c:
                break
            if c == 1:
                del delayed[v]
            else:
                delayed[v] = c - 1
            heappop(heap)

    def rebalance():
        nonlocal low_size, high_size
        # invariant: low_size == high_size or low_size == high_size + 1
        if low_size > high_size + 1:
            heappush(high, -heappop(low))
            low_size -= 1
            high_size += 1
            prune(low, -1)
        elif low_size < high_size:
            heappush(low, -heappop(high))
            high_size -= 1
            low_size += 1
            prune(high, 1)

    def add(x):
        nonlocal low_size, high_size
        if not low or x <= -low[0]:
            heappush(low, -x)
            low_size += 1
        else:
            heappush(high, x)
            high_size += 1
        rebalance()

    def remove(x):
        nonlocal low_size, high_size
        delayed[x] = delayed.get(x, 0) + 1
        if x <= -low[0]:
            low_size -= 1
            if x == -low[0]:
                prune(low, -1)
        else:
            high_size -= 1
            if x == high[0]:
                prune(high, 1)
        rebalance()

    for i, x in enumerate(readings):
        if x is not None:
            add(x)
        if i >= k:
            old = readings[i - k]
            if old is not None:
                remove(old)
        out.append(-low[0] if low_size else None)
    return out

TWO_CHAR_OPS = ("==", "!=", "<=", ">=", "->")
ONE_CHAR_OPS = "<>=+-*/(),"
ESCAPES = {'"': '"', "\\": "\\", "n": "\n", "t": "\t"}


def _is_digit(ch):
    return "0" <= ch <= "9"


def _is_ident_start(ch):
    return ch == "_" or "a" <= ch <= "z" or "A" <= ch <= "Z"


def _is_ident_char(ch):
    return _is_ident_start(ch) or _is_digit(ch)


def tokenize(src):
    tokens = []
    n = len(src)
    i, line, col = 0, 1, 1

    def fail(at_line, at_col, message):
        raise ValueError("line %d col %d: %s" % (at_line, at_col, message))

    while i < n:
        ch = src[i]

        if ch == "\n":
            i += 1
            line += 1
            col = 1
            continue
        if ch == " " or ch == "\t":
            i += 1
            col += 1
            continue
        if ch == "#":
            end = src.find("\n", i)
            if end == -1:
                i = n
            else:
                i = end + 1
                line += 1
                col = 1
            continue

        if _is_digit(ch):
            j = i
            while j < n and _is_digit(src[j]):
                j += 1
            is_float = False
            if j + 1 < n and src[j] == "." and _is_digit(src[j + 1]):
                j += 2
                while j < n and _is_digit(src[j]):
                    j += 1
                is_float = True
            if j < n and src[j] in "eE":
                k = j + 1
                if k < n and src[k] in "+-":
                    k += 1
                if k < n and _is_digit(src[k]):
                    while k < n and _is_digit(src[k]):
                        k += 1
                    j = k
                    is_float = True
            text = src[i:j]
            tokens.append(("NUMBER", float(text) if is_float else int(text), line, col))
            col += j - i
            i = j
            continue

        if _is_ident_start(ch):
            j = i
            while j < n and _is_ident_char(src[j]):
                j += 1
            tokens.append(("IDENT", src[i:j], line, col))
            col += j - i
            i = j
            continue

        if ch == '"':
            j = i + 1
            chars = []
            while True:
                if j >= n or src[j] == "\n":
                    fail(line, col, "unterminated string")
                c = src[j]
                if c == '"':
                    j += 1
                    break
                if c == "\\":
                    if j + 1 >= n or src[j + 1] == "\n":
                        fail(line, col, "unterminated string")
                    if src[j + 1] not in ESCAPES:
                        fail(line, col + (j - i), "bad escape")
                    chars.append(ESCAPES[src[j + 1]])
                    j += 2
                    continue
                chars.append(c)
                j += 1
            tokens.append(("STRING", "".join(chars), line, col))
            col += j - i
            i = j
            continue

        if src[i:i + 2] in TWO_CHAR_OPS:
            tokens.append(("OP", src[i:i + 2], line, col))
            i += 2
            col += 2
            continue
        if ch in ONE_CHAR_OPS:
            tokens.append(("OP", ch, line, col))
            i += 1
            col += 1
            continue

        fail(line, col, "unexpected character %r" % ch)

    return tokens
